  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider      = \"prisma-client-js\"\n  // output   = \"../node_modules/.prisma/client\" // Removido para usar o default\n  binaryTargets = [\"native\", \"linux-musl-openssl-3.0.x\"]\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel User {\n  id        String   @id @default(cuid())\n  email     String   @unique\n  password  String\n  name      String?\n  role      UserRole @default(USER) // Alterado de roles String[]\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  // Relação com Client (um User pode ser um Client)\n  client    Client?\n}\n\n// Novo Enum UserRole (como no frontend)\nenum UserRole {\n  USER\n  ADMIN\n}\n\n// Novo Modelo Client (como no frontend)\nmodel Client {\n  id           String        @id @default(cuid())\n  name         String\n  phone        String?\n  email        String?       @unique // Pode ser diferente do User.email ou o mesmo se logado\n  address      String?\n  pets         Pet[]\n  appointments Appointment[]\n  createdAt    DateTime      @default(now())\n  updatedAt    DateTime      @updatedAt\n\n  // Opcional: se um cliente está associado a uma conta de usuário do sistema\n  userId String? @unique\n  user   User?   @relation(fields: [userId], references: [id])\n}\n\nmodel Pet {\n  id           String        @id @default(cuid())\n  name         String\n  species      String\n  breed        String?\n  birthDate    DateTime?\n  clientId     String\n  client       Client        @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  appointments Appointment[]\n  observations String?\n\n  // Campos adicionados para alinhar com o frontend\n  foodType         String?\n  lastTickMedicine Json? // { \"name\": \"string\", \"date\": \"string\" }\n  rabiesVaccine    Json? // { \"isUpToDate\": boolean, \"lastDate\": \"string\" }\n  vaccineHistory   Json[] // Array de { \"name\": \"string\", \"date\": \"string\" }\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// Novo Modelo Groomer (como no frontend)\nmodel Groomer {\n  id                   String        @id @default(cuid())\n  name                 String\n  phone                String?\n  email                String?       @unique\n  specialties          String[]\n  status               String        @default(\"available\") // \"available\" or \"busy\"\n  commissionPercentage Float         @default(20)\n  appointments         Appointment[]\n  createdAt            DateTime      @default(now())\n  updatedAt            DateTime      @updatedAt\n}\n\nmodel Package {\n  id                String   @id @default(cuid())\n  name              String\n  description       String?\n  includesBaths     Int\n  includesGrooming  Boolean\n  includesHydration Boolean\n  basePrice         Float\n  pickupPrice       Float\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n}\n\n// Renomeado de ServiceType para Service e ajustado (como no frontend)\nmodel ServicePackage {\n  id                  String               @id @default(cuid())\n  name                String               @unique\n  description         String?\n  price               Float\n  durationMin         Int\n  appointmentServices AppointmentService[]\n  createdAt           DateTime             @default(now())\n  updatedAt           DateTime             @updatedAt\n}\n\nmodel Appointment {\n  id         String            @id @default(cuid())\n  dateTime   DateTime // Renomeado de appointmentDateTime\n  status     AppointmentStatus @default(SCHEDULED) // Alterado de String e adicionado enum\n  notes      String?\n  totalPrice Float // Adicionado\n\n  clientId  String\n  client    Client   @relation(fields: [clientId], references: [id])\n  petId     String\n  pet       Pet      @relation(fields: [petId], references: [id])\n  groomerId String?\n  groomer   Groomer? @relation(fields: [groomerId], references: [id]) // Adicionado\n\n  appointmentServices AppointmentService[] // Adicionado para relação N-N com Service\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Removida relação direta com ServiceType:\n  // serviceType         ServiceType @relation(fields: [serviceTypeId], references: [id])\n  // serviceTypeId       String\n}\n\n// Novo: Tabela de junção para Appointment e Service (como no frontend)\nmodel AppointmentService {\n  id            String         @id @default(cuid())\n  appointmentId String\n  appointment   Appointment    @relation(fields: [appointmentId], references: [id], onDelete: Cascade)\n  serviceId     String\n  service       ServicePackage @relation(fields: [serviceId], references: [id])\n  priceAtTime   Float // Preço do serviço no momento do agendamento\n  quantity      Int            @default(1)\n  createdAt     DateTime       @default(now())\n\n  @@unique([appointmentId, serviceId])\n}\n\n// Novo Enum AppointmentStatus (como no frontend)\nenum AppointmentStatus {\n  SCHEDULED\n  CONFIRMED\n  IN_PROGRESS\n  COMPLETED\n  CANCELLED\n  NO_SHOW\n}\n",
